"""
Mechanics for implementing contract consumers (contract-enabled callables).
"""

from __future__ import annotations

from functools import wraps
from inspect import signature
from typing import Any, Callable

from .contracts import (
    ContractData,
    TafContract,
    call_provider,
    contracts_by_data_type,
    get_provided_contracts,
)
from .signature_checks import get_supported_data_types


# TODO: typehint and the return value func properly
def contract_consumer(
    func=None, *, robot_name: str | None = None, contract_arg: str = "contract_data"
) -> Callable[[Any], Any]:
    """Use this decorator to add contract support to a function.

    The decorated function will be able to accept any object that provides data
    for at least one contract supported by this function.

    To use this decorator, the argument named in ``contract_arg`` must be typed
    with a contract class or an union of them. This defines the prtoocols that
    the decorated callable supports.

    Example::

        from taf.internal.contracts import contract_consumer, SshClientConfig

        @contract_consumer
        def my_ssh_keyword(
            contract: SshClientConfig
        ) -> None:
            print(contract.host, contract.username, contract.password)

    In the example above the ``my_ssh_keyword`` function can accept any object
    that supports the `Ssh` contract, i.e. any class that implements the
    ``__taf_contract_ssh__`` method.

    If multiple contracts are supported, and the value passed to the function
    supports a subset of them, the contracts specified in the type hint as
    first take priority.

    Use ``robot_name`` argument to provide a specific Robot Framework keyword
    name and utilize the "argument embedding syntax"::

        @contract_consumer(
            robot_name="Connect to: ${contract: [^(]+} (aliased as ${alias})"
        )
        def my_ssh_keyword(contract: SshClientConfig, alias):
            ...

    The keyword above can now be used in a fashion similar to the ``Connect
    To`` keyword from taf.transport.ssh.

    :param str robot_name: Optional name of the keyword as seen by Robot
        Framework. Similar to the ``name`` argument from the
        ``@robot.api.deco.keyword`` decorator.
    :param str contract_arg: Name of the argument that will be used to pass the
        contract data, the type hint of which will be used to determine the
        supported contracts. ``"contract"`` by default.
    """

    def _contract_consumer(func: Callable) -> Callable:
        """A decorator that adds contract support to a function."""
        supported_data_types = get_supported_data_types(func, contract_arg)
        func_signature = signature(func)

        @wraps(func)
        def taf_contract_wrapper(*args, **kwargs):
            bound_args = func_signature.bind(*args, **kwargs)
            contract_object = bound_args.arguments[contract_arg]
            chosen_contract = choose_contract(
                supported_data_types, contract_object, contract_arg
            )
            contract_data = call_provider(chosen_contract, contract_object)
            bound_args.arguments[contract_arg] = contract_data

            args = bound_args.args
            kwargs = bound_args.kwargs

            return func(*args, **kwargs)

        if robot_name is not None:
            # This is how Robot Framework does this under the hood when using
            # the @keyword decorator.
            taf_contract_wrapper.robot_name = robot_name  # type: ignore
        taf_contract_wrapper.robot_types = None  # type: ignore

        return taf_contract_wrapper

    if func:
        return _contract_consumer(func)

    return _contract_consumer


def choose_contract(
    supported_data_types: list[type[ContractData]],
    contract_object: type[TafContract],
    contract_arg: str,
) -> type[TafContract]:
    consumer_supported: list[type[TafContract]] = [
        contracts_by_data_type[data_type] for data_type in supported_data_types
    ]
    provided = get_provided_contracts(contract_object)
    if not provided:
        raise TypeError(
            f"expected a TAF-contract-supporting object. "
            f"Given object does not support any TAF contracts: {contract_object!r}"
        )
    # We choose the first supported contract that is provided by the object
    if not any(
        contract for contract in consumer_supported if (first := contract) in provided
    ):
        raise TypeError(
            f"the object given via {contract_arg} parameter is not compatible "
            f"with any of the contracts supported by this keyword. The object "
            f"supports: {provided}, the keyword supports: {consumer_supported}"
        )
    return first
